const preview = () => config.preview;
const supportLink = () => config.supportEmail?`<a href="mailto:${esc(config.supportEmail)}">${esc(config.supportEmail)}</a>`:'our support team';
const FDA = 'These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease.';
const priceLabel = p => p.isConcept?'Concept price':p.isSample?'Sample price':!p.priceConfirmed?'Preview price':'';
