function supplementFacts(p){
 if(!p.factsVerified&&!p.labelVerified)return '<p>Supplement Facts have not been supplied for this product.</p>';
 return `<div class="facts-accessible"><p><strong>Serving size:</strong> ${esc(p.servingSize)}<br/><strong>Servings per container:</strong> ${p.servings}${p.servingsVerified===false?' (supplied label; awaiting confirmation)':''}</p><table><caption>Declared amounts per serving</caption><thead><tr><th scope="col">Ingredient</th><th scope="col">Amount</th></tr></thead><tbody>${p.formula.map(f=>`<tr><th scope="row">${esc(f.name)}</th><td>${esc(f.amount)}</td></tr>`).join('')}</tbody></table><p><strong>Other ingredients:</strong> ${esc((p.otherIngredients||[]).join(', '))}.</p><p class="facts-caffeine">${esc(p.caffeineNote)}</p>${p.supplementFactsImage?`<a href="${esc(p.supplementFactsImage)}" target="_blank" rel="noopener">Open the full Supplement Facts panel ↗</a>`:''}</div>`;
}
function detailGallery(p){
 const photos=productGallery(p),index=Math.min(view.galleryIndex||0,photos.length-1);
 return `<div class="detail-main-image ${photos[index].kind==='label'?'flat-label-view':''}"><button type="button" class="detail-gallery-image" data-action="zoomGallery" data-id="${esc(p.id)}" aria-label="Enlarge ${esc(photos[index].label)}">${galleryPhoto(photos[index],{hero:true})}<span class="zoom-hint">${icon('plus',17)} ENLARGE IMAGE</span></button>${p.isConcept?'<span class="detail-demo-tag">AUCTORAN LABS / DESIGN CONCEPT</span>':p.isSample?'<span class="detail-demo-tag">ILLUSTRATIVE CATEGORY IMAGE / SAMPLE LISTING</span>':''}</div>${photos.length>1?`<div class="gallery-tools"><span>${String(index+1).padStart(2,'0')} / ${String(photos.length).padStart(2,'0')}</span><span>SWIPE TO EXPLORE</span><div><button type="button" aria-label="Previous image" data-action="galleryPrevious" data-id="${esc(p.id)}">←</button><button type="button" aria-label="Next image" data-action="galleryNext" data-id="${esc(p.id)}">→</button></div></div><div class="detail-image-row" role="group" aria-label="${esc(p.name)} gallery">${photos.map((photo,i)=>`<button type="button" data-action="showDetailImage" data-id="${esc(p.id)}" data-photo="${i}" aria-pressed="${i===index}" aria-label="View ${esc(photo.label)}">${galleryPhoto(photo)}<span class="gallery-photo-label">${esc(photo.label)}</span></button>`).join('')}</div>`:''}<p class="gallery-caption" aria-live="polite">${esc(photos[index].alt)}</p>`;
}
function detail(slug){const p=products.find(x=>x.slug===slug);if(!p)return notFound();const flagship=p.id==='fortivor-pre-workout';
 return `<main class="detail-page"><nav class="breadcrumbs" aria-label="Breadcrumbs"><a href="/" data-route>HOME</a><span>/</span><a href="/shop" data-route>SHOP</a><span>/</span><a href="/shop?category=${p.categoryKey}" data-route>${esc(p.category.toUpperCase())}</a><span>/</span><strong>${esc(p.name.toUpperCase())}</strong></nav><div class="detail-layout"><section class="detail-media" aria-label="Product gallery">${detailGallery(p)}</section><section class="detail-info"><p class="kicker">${p.isConcept?'AUCTORAN LABS / DESIGN CONCEPT':flagship?'AUCTORAN LABS PRE-WORKOUT':'CURATED BRANDS / SAMPLE'}</p><p class="detail-brand">${esc(p.brand)}</p><h1>${esc(p.name)}<span class="detail-period">.</span></h1><p class="detail-type">${esc(p.category)}${p.servings&&p.servingSizeVerified!==false?' / '+p.servings+' SERVINGS':p.servingSizeVerified===false?' / SERVING SIZE PENDING':''}</p><div class="detail-separator"></div><div class="detail-price"><strong>${money(p.priceCents)}</strong><span>${p.priceConfirmed?'USD · shipping & tax at checkout':'Preview price · final approval pending'}</span></div><p class="detail-description">${esc(p.description)}</p><p class="stock-status"><span></span>${stockLabel(p)}</p><div class="variant-block"><label for="flavor-choice">${flagship?(p.packagingDetailsConfirmed?'FLAVOR':'SHOWN FLAVOR'):'FORMAT'}</label><select id="flavor-choice" aria-label="${flagship?'Available flavor':'Product format'}"><option>${esc(p.flavor)}</option></select></div><div class="variant-block"><span class="variant-label">CONTAINER</span><span class="size-text">${esc(p.size)}</span></div><div class="purchase-controls" id="primary-purchase"><div class="quantity-control"><button type="button" aria-label="Decrease quantity" data-action="detailMinus">${icon('minus',16)}</button><output aria-live="polite">${view.detailQty}</output><button type="button" aria-label="Increase quantity" data-action="detailPlus">${icon('plus',16)}</button></div><button class="btn dark-btn add-detail" data-action="addDetail" data-id="${esc(p.id)}" ${canBuy(p)?'':'disabled'}>${canBuy(p)?`${p.demoAvailable?'ADD TO DEMO BAG':'ADD TO BAG'} — ${money(p.priceCents*view.detailQty)} ${icon('arrow',20)}`:'NOT AVAILABLE YET'}</button></div><p class="purchase-note">${p.demoAvailable?(config.mode==='stripe-test'?'Stripe test purchase flow. No real payment.':'Preview purchase flow. No payment or real order in demo mode.'):config.mode==='stripe-test'?'Stripe test checkout. No real payment.':'Secure guest checkout by Stripe.'}</p><div class="purchase-service"><a href="/info/shipping" data-route>US SHIPPING ${icon('northeast',13)}</a><a href="/info/returns" data-route>RETURNS & CARE ${icon('northeast',13)}</a></div><p class="shipping-detail">${config.preview?'Shipping rates and processing terms will be confirmed before launch.':`Dispatch within ${esc(config.store.processingDays)}. ${config.shippingCents===0?'Complimentary US shipping.':config.shippingConfigured?'US shipping from '+money(config.shippingCents)+'.':'Shipping at checkout.'}`}</p>${flagship?'<nav class="product-jumps" aria-label="Product information"><a href="#formula">The formula ↓</a><a href="#supplement-information">Label & use ↓</a><a href="#product-faq">FAQs ↓</a></nav>':''}<div class="accordion-list" id="supplement-information"><details><summary>SUPPLEMENT FACTS ${icon('plus',16)}</summary>${supplementFacts(p)}</details><details><summary>SUGGESTED USE ${icon('plus',16)}</summary><p>${p.directionsVerified&&p.suggestedUse?esc(p.suggestedUse):'Approved usage directions have not been supplied. Do not use the serving-size line or this preview as dosing instructions. Follow the final approved directions before use.'}</p></details><details><summary>CAFFEINE & SAFETY ${icon('plus',16)}</summary><p>${esc(p.warning||'Verified ingredients, allergens and safety information have not been supplied. This is a sample listing, not an offer for sale.')}</p>${flagship?`<p class="fda-note">${FDA}</p>`:''}</details><details><summary>SHIPPING & RETURNS ${icon('plus',16)}</summary><p>${config.preview?'Policy text is awaiting operational approval.':'US shipping and returns are subject to the published store policies.'} See <a href="/info/shipping" data-route>shipping details</a> and <a href="/info/returns" data-route>returns policy</a>. Shipping and tax are shown before payment.</p></details></div></section></div>
 ${flagship?`<section class="pdp-formula" id="formula"><div class="pdp-formula-intro"><p class="kicker">FORTIVOR / FORMULA TRANSPARENCY</p><h2>KNOW<br/><em>WHAT’S IN IT.</em></h2><p>Explore the full formula supplied by Auctoran Labs. Select an ingredient to learn more.</p><p class="formula-verification">${p.factsVerified?'Ingredient amounts are confirmed from the supplied product information. Serving size and directions are still awaiting confirmation.':'Ingredient details are awaiting confirmation.'}</p><p class="pdp-caution"><strong>CAFFEINE INFORMATION</strong><br/>Approximately ${p.caffeineMg} mg caffeine per declared serving, including caffeine from guarana. For adults 18+. Avoid other stimulants. Not for pregnancy or nursing. Read the complete warnings and approved directions before use.</p></div><div class="interactive-formula">${p.formula.map((f,i)=>`<details ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span><b>${esc(f.name)}</b><strong>${esc(f.amount)}</strong>${icon('plus',16)}</summary><p>${esc(ingredientNotes[f.name]||'See the approved label for information.')}</p></details>`).join('')}<p class="formula-fine">${esc(p.flavor.toUpperCase())}<br/>Serving size and directions awaiting confirmation. Outcomes are not guaranteed.</p></div></section><section class="pdp-faq" id="product-faq"><p class="kicker">BEFORE YOUR NEXT SESSION</p><h2>GOOD <em>QUESTIONS.</em></h2>${[['What flavor is Fortivor?',`${p.flavor}. The supplied package shows 25 servings, but serving size and the final serving count are awaiting confirmation.`],['Can I combine Fortivor with other stimulants?','Fortivor contains approximately 355 mg total caffeine per declared serving: 300 mg caffeine anhydrous plus approximately 55 mg from guarana. It also contains theobromine. Avoid combining it with other caffeine or stimulant products. Consult a qualified healthcare professional about suitability, especially if you take medication or have a medical condition.'],['Where are the customer reviews?','Customer reviews will be available after launch.'],['When will my order ship?',config.preview?'This storefront is a demonstration. No real order is placed or shipped. Shipping rates, stock and operational terms must be confirmed before launch.':`Orders are processed within ${config.store.processingDays}. See the shipping and returns policies for details.`]].map(([q,a])=>`<details><summary>${q} ${icon('plus',19)}</summary><p>${esc(a)}</p></details>`).join('')}</section>`:''}
 <section class="detail-after visual-detail-after"><div>${campaignPhoto('women-preparation','A woman preparing her wrist wrap for the next set')}</div><div><p class="kicker">A CONSIDERED ROUTINE</p><h2>MAKE IT<br/><em>YOUR ROUTINE.</em></h2><p>Explore a selection guided by your training goal and preferences.</p><a href="/build-your-stack" data-route class="btn dark-btn">BUILD YOUR STACK ${icon('arrow')}</a></div></section>
 <div class="mobile-purchase" aria-label="Quick product purchase" hidden><div><strong>${esc(p.name)}</strong><span>${money(p.priceCents*view.detailQty)}${p.demoAvailable?' · PREVIEW':''}</span></div><button class="btn ivory" data-action="addDetail" data-id="${esc(p.id)}" ${canBuy(p)?'':'disabled'}>${p.demoAvailable?'ADD TO DEMO BAG':'ADD TO BAG'} ${icon('plus',17)}</button></div>
 <dialog id="gallery-zoom" class="gallery-zoom" aria-label="Enlarged product gallery"><div class="zoom-toolbar"><p>${esc(p.name)} / ${esc(productGallery(p)[view.galleryIndex||0]?.label)}</p><div class="zoom-actions"><button type="button" class="zoom-scale" data-action="toggleZoom" aria-pressed="true">FULL VIEW</button><button type="button" data-action="closeZoom" aria-label="Close enlarged image">${icon('close',24)}</button></div></div><div class="zoom-content" tabindex="0" aria-label="Enlarged image. Scroll or use arrow keys to explore."></div><p class="zoom-help">Scroll or swipe to inspect. Select Full view to see the whole image.</p></dialog></main>`;
}
let stack = {step:1,goal:'',categories:[],stimulant:'any',budgetCents:'',allowPreview:false,selection:{}};
function stackResults(){return matchProducts(products,stack,{preview:config.preview}).filter(r=>!(stack.removed||[]).includes(r.product.id));}
function selectedStack(){return stackResults().filter(r=>stack.selection[r.product.id]>0);}
function stackTotal(){return selectedStack().reduce((n,r)=>n+r.product.priceCents*stack.selection[r.product.id],0);}
function stackPage(){
 const results=stack.step===3?stackResults():[];
 return `<main class="stack-page"><section class="stack-heading visual-stack-heading"><div class="stack-hero-copy"><p class="kicker">THE ROUTINE / BUILT AROUND YOU</p><h1>BUILD YOUR<br/><em>STACK.</em></h1><p>Your training. Your preferences. A considered selection.</p></div><div class="stack-hero-photo">${campaignPhoto('women-preparation','A woman preparing her wrist wrap between strength-training sets')}</div></section><section class="stack-workspace" aria-label="Supplement stack builder"><ol class="stack-progress" aria-label="Your progress">${['Your goal','Your preferences','Your selection'].map((name,i)=>`<li class="${stack.step===i+1?'current':stack.step>i+1?'complete':''}" ${stack.step===i+1?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${name}</li>`).join('')}</ol><div class="stack-stage" aria-live="polite">
 ${stack.step===1?`<p class="kicker">STEP 01 / SET THE DIRECTION</p><h2>WHAT BRINGS YOU<br/><em>TO THE WEIGHT ROOM?</em></h2><p class="stage-description">Choose the goal closest to your current routine.</p><div class="goal-grid" role="group" aria-label="Training goal">${GOALS.map(([id,name,desc],i)=>`<button type="button" data-action="stackGoal" data-id="${id}" aria-pressed="${stack.goal===id}" class="goal-choice ${stack.goal===id?'selected':''}"><span>0${i+1}</span><strong>${name}</strong><p>${desc}</p><span class="goal-check">${stack.goal===id?icon('check',17):icon('northeast',17)}</span></button>`).join('')}</div><div class="stack-stage-actions"><span>ONE GOAL. A CLEARER START.</span><button class="btn dark-btn" data-action="stackNext" ${stack.goal?'':'disabled'}>CONTINUE ${icon('arrow')}</button></div>`:''}
 ${stack.step===2?`<p class="kicker">STEP 02 / MAKE IT YOURS</p><h2>KEEP WHAT<br/><em>WORKS FOR YOU.</em></h2><fieldset class="stack-fieldset"><legend>PRODUCT CATEGORIES <span>Optional · leave empty to use goal categories</span></legend><div class="stack-category-options">${CATEGORIES.map(([id,name])=>`<label><input type="checkbox" name="stack-category" value="${id}" ${stack.categories.includes(id)?'checked':''}/><span>${name}</span></label>`).join('')}</div></fieldset><fieldset class="stack-fieldset"><legend>STIMULANT PREFERENCE</legend><div class="stimulant-options">${[['any','No preference'],['caffeinated','Caffeinated'],['free','Stimulant-free']].map(([id,name])=>`<label><input type="radio" name="stack-stimulant" value="${id}" ${stack.stimulant===id?'checked':''}/><span>${name}</span></label>`).join('')}</div><p class="field-help">Only products with known caffeine data are eligible. At most one caffeinated product is suggested.</p></fieldset><div class="budget-field"><label for="stack-budget">TOTAL BUDGET <span>Optional · USD</span></label><select id="stack-budget"><option value="">No set budget</option>${[['3000','Up to $30'],['5000','Up to $50'],['7500','Up to $75'],['10000','Up to $100']].map(([id,name])=>`<option value="${id}" ${stack.budgetCents===id?'selected':''}>${name}</option>`).join('')}</select></div>${config.preview?`<div class="stack-preview-option"><label><input type="checkbox" id="stack-preview" ${stack.allowPreview?'checked':''}/><span>Include the Fortivor preview in demo matching</span></label><p>No verified inventory is currently supplied. Opt in to see how matching works with the Fortivor concept. Sample partner products remain excluded; no real purchase is possible.</p></div>`:''}<div class="stack-stage-actions"><button class="underlined-link" data-action="stackBack">← BACK TO GOAL</button><button class="btn dark-btn" data-action="stackNext">SEE MY SELECTION ${icon('arrow')}</button></div>`:''}
 ${stack.step===3?`<p class="kicker">STEP 03 / YOUR CONSIDERED SELECTION</p><h2>THE NEXT<br/><em>PART OF YOUR ROUTINE.</em></h2><p class="stage-description">${esc(GOALS.find(g=>g[0]===stack.goal)?.[1])} · ${stack.stimulant==='free'?'Stimulant-free':stack.stimulant==='caffeinated'?'Caffeinated':'No stimulant preference'}${stack.budgetCents?' · Budget '+money(Number(stack.budgetCents)):''}</p>${results.length?`<div class="stack-results">${results.map(({product:p,demo,rationale})=>`<article class="stack-result"><a href="/product/${p.slug}" data-route class="stack-result-image">${productImage(p,{sizes:"(max-width:700px) 80px, 210px"})}</a><div><p class="kicker">${demo?'DEMONSTRATION MATCH':'CATALOG MATCH'}</p><span class="brand-label">${esc(p.brand)}</span><h3>${esc(p.fullName)}</h3><strong class="stack-result-price">${money(p.priceCents)} ${demo?'<small>Preview price</small>':''}</strong><p>${esc(rationale)}</p>${p.caffeineMg>0?`<p class="stack-caffeine">${p.caffeineMg} mg caffeine per stated serving${p.caffeineVerified?'':' · concept label'}. Avoid other stimulants; read warnings before use.</p>`:''}<div class="stack-result-actions"><label class="stack-select"><input type="checkbox" data-stack-select="${p.id}" ${stack.selection[p.id]>0?'checked':''}/> Include</label><div class="quantity-control compact"><button aria-label="Decrease ${esc(p.name)} stack quantity" data-action="stackMinus" data-id="${p.id}">${icon('minus',15)}</button><output>${stack.selection[p.id]||1}</output><button aria-label="Increase ${esc(p.name)} stack quantity" data-action="stackPlus" data-id="${p.id}">${icon('plus',15)}</button></div><button class="underlined-link" data-action="stackRemove" data-id="${p.id}">REMOVE</button><button class="btn dark-btn" data-action="addStackSingle" data-id="${p.id}">${demo?'ADD DEMO ITEM':'ADD TO BAG'} ${icon('plus',15)}</button></div></div></article>`).join('')}</div><div class="stack-checkout"><div><span>SELECTED SUBTOTAL</span><strong>${money(stackTotal())}</strong><small>${results.some(r=>r.demo)?'Demonstration only · no real inventory':'Shipping and tax at checkout'}</small></div><button class="btn dark-btn" data-action="addStack" ${!selectedStack().length||(stack.budgetCents&&stackTotal()>Number(stack.budgetCents))?'disabled':''}>ADD SELECTED TO ${results.some(r=>r.demo)?'DEMO BAG':'BAG'} ${icon('arrow')}</button><p class="stack-budget-warning" role="status">${stack.budgetCents&&stackTotal()>Number(stack.budgetCents)?'Your selected quantities exceed your budget. Adjust quantities to continue.':''}</p></div>`:`<div class="stack-empty"><span>01 / A CLEAR ANSWER</span><h3>NO SUITABLE PRODUCTS. <em>YET.</em></h3><p>No verified, available products match these preferences. We exclude sample brands, unverified caffeine data, and products over your budget.${stack.allowPreview?' Your chosen preferences also exclude the Fortivor concept.':''}</p><a href="/shop" data-route class="underlined-link">EXPLORE THE COLLECTION ${icon('arrow',16)}</a></div>`}<div class="stack-stage-actions"><button class="underlined-link" data-action="stackBack">← EDIT PREFERENCES</button><button class="underlined-link" data-action="stackReset">START AGAIN ↗</button></div><details class="matching-rules"><summary>HOW MATCHING WORKS ${icon('plus',16)}</summary><p>Products must match a category relevant to your goal and your category choices. We require confirmed stock, price, label and caffeine information. We select at most three products, one per category, at most one with caffeine, within your combined budget for one of each. Category relevance, then lower price and product ID determine the order. Quantity changes update the total. Opted-in preview results use only the Fortivor concept. No sample partner products are recommended.</p></details>`:''}
 </div><p class="stack-disclaimer">Catalog matching, not medical advice. These suggestions do not assess your health, medications, diet or nutritional needs. Read product labels and consult a qualified healthcare professional about suitability.</p></section></main>`;
}
function cartPage(){const cancelled=new URLSearchParams(location.search).has('cancelled');return `<main class="cart-page"><p class="kicker">YOUR SHOPPING BAG</p><h1>THE <em>BAG.</em></h1>${cancelled&&cart.length?'<p class="cart-notice" role="status">Checkout was cancelled. Your bag is saved, nothing was charged.</p>':''}${cart.length?`<div class="cart-layout"><div class="cart-list"><p class="cart-progress">01 BAG <span>→</span> 02 SECURE CHECKOUT <span>→</span> 03 CONFIRMATION</p>${cart.map(cartLine).join('')}</div><aside class="cart-summary"><p class="kicker">ORDER SUMMARY</p><div class="summary-line"><span>Subtotal (${count()} items)</span><strong>${money(total())}</strong></div><div class="summary-line"><span>Shipping & tax</span><span>${config.shippingConfigured?money(config.freeShippingOverCents!==null&&total()>=config.freeShippingOverCents?0:config.shippingCents)+' shipping; tax at checkout':'Confirmed at checkout'}</span></div><div class="summary-total"><span>SUBTOTAL</span><strong>${money(total())}</strong></div><p id="checkout-error" class="checkout-error" role="alert"></p><button class="btn dark-btn fullwidth" data-action="checkout" ${view.checkoutLoading?'disabled':''}>${view.checkoutLoading?'PREPARING CHECKOUT…':config.mode==='demo'?'TRY DEMO CHECKOUT':'SECURE CHECKOUT'} ${icon('arrow')}</button><p class="summary-disclaimer">${config.mode==='demo'?'DEMO ONLY — no payment is taken and no order is created.':'You will be redirected to Stripe for secure guest checkout.'}</p><a href="/shop" data-route class="underlined-link">CONTINUE SHOPPING ${icon('arrow',16)}</a></aside></div>`:`<div class="empty-cart visual-empty-cart"><div class="empty-bag-copy"><h2>READY FOR<br/><em>WHAT’S NEXT?</em></h2><p>Your bag is empty. Explore the essentials for your next session.</p><a href="/shop" data-route class="btn dark-btn">SHOP SUPPLEMENTS ${icon('arrow')}</a></div><a href="/product/fortivor-pre-workout" data-route class="empty-bag-visual" aria-label="Explore Fortivor">${productImage(byId('fortivor-pre-workout'))}</a></div>`}</main>`;}
function cartLine(item){const p=byId(item.id);if(!p)return '';return `<article class="cart-line"><a href="/product/${esc(p.slug)}" data-route class="cart-thumb">${productImage(p,{sizes:"90px"})}</a><div class="cart-line-main"><span class="brand-label">${esc(p.brand)}</span><a href="/product/${esc(p.slug)}" data-route class="cart-line-title">${esc(p.name)}</a><small>${esc(p.category)} ${p.isConcept?'· design concept':p.isSample?'· sample listing':''}</small><button class="remove-link" data-action="remove" data-id="${esc(p.id)}">REMOVE</button></div><div class="cart-line-side"><strong>${money(p.priceCents*item.qty)}</strong><div class="quantity-control compact"><button aria-label="Remove one ${esc(p.name)}" data-action="decrease" data-id="${esc(p.id)}">${icon('minus',15)}</button><output>${item.qty}</output><button aria-label="Add one ${esc(p.name)}" data-action="increase" data-id="${esc(p.id)}">${icon('plus',15)}</button></div></div></article>`;}
function about(){return `<main class="about-page"><section class="brand-hero"><div class="brand-hero-copy"><p class="kicker">ABOUT AUCTORAN LABS</p><h1>BUILT AROUND<br/><em>THE WORK.</em></h1><p>For the way you train.<br/>A considered approach to your everyday.</p></div><div class="brand-hero-photo">${campaignPhoto('women-strength','A woman standing tall at the top of a barbell deadlift',{hero:true})}</div></section><section class="brand-story"><figure>${campaignPhoto('women-preparation','A woman taking time to prepare between strength-training sets')}<figcaption>TIME TO PREPARE. ROOM TO PROGRESS.</figcaption></figure><div><p class="kicker">OUR POINT OF VIEW</p><h2>DISCIPLINE<br/>IN THE <em>DETAILS.</em></h2><p>Training looks different for everyone. Our focus is the person behind the routine: your goals, your choices, and the preparation that makes a session your own.</p><p>Fortivor is our signature pre-workout. The formula is presented ingredient by ingredient, so you can understand what you are considering before it becomes part of your training.</p><a href="/product/fortivor-pre-workout" data-route class="underlined-link">MEET FORTIVOR ${icon('arrow',16)}</a></div></section><section class="brand-principles"><p class="kicker">WHAT GUIDES US</p><div><article><span>01</span><h3>Know the formula.</h3><p>Clear ingredient amounts and accessible product information. Read the label, directions and warnings before use.</p></article><article><span>02</span><h3>Choose with intent.</h3><p>Our stack builder explains its product matches. Your preferences guide the selection; it is not medical advice.</p></article><article><span>03</span><h3>Make it a routine.</h3><p>Supplements are one part of training. We keep the experience focused on the essentials and the work around them.</p></article></div></section><section class="routine-invitation"><div class="routine-photo">${campaignPhoto('training','A man completing a barbell deadlift with controlled technique')}</div><div class="routine-copy"><p class="kicker">FIND YOUR ESSENTIALS</p><h2>BEFORE<br/><em>THE FIRST REP.</em></h2><p>Explore Fortivor or build a selection around how you train.</p><a href="/shop" data-route class="btn ivory">EXPLORE SUPPLEMENTS ${icon('arrow')}</a></div></section></main>`;}
function fill(text){const s=config.store;const ship=config.shippingCents===null||config.shippingCents===undefined?'Shipping is calculated at checkout.':config.shippingCents===0?'US shipping is complimentary on every order.':`Standard US shipping is ${money(config.shippingCents)} per order${config.freeShippingOverCents!=null?`, free on orders of ${money(config.freeShippingOverCents)} or more`:''}.`;
 return esc(text).replace(/\{(\w+)\}/g,(m,key)=>key==='supportEmail'?supportLink():key==='shippingLine'?esc(ship):esc(s[key]??m));}
function careNavigation(active){return `<nav class="care-navigation" aria-label="Customer care">${[['shipping','Shipping','/info/shipping'],['returns','Returns','/info/returns'],['contact','Contact','/contact'],['privacy','Privacy','/info/privacy'],['terms','Terms','/info/terms']].map(([id,label,url])=>`<a href="${url}" data-route ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function careAside(){return `<aside class="care-aside"><figure>${campaignPhoto('women-preparation','A woman preparing for her next set in the gym')}<figcaption>AUCTORAN LABS / CUSTOMER CARE</figcaption></figure><p>Everything you need for a considered purchase.</p><a href="/product/fortivor-pre-workout" data-route class="underlined-link">EXPLORE FORTIVOR ${icon('arrow',16)}</a></aside>`;}
function policyPage(key){const policy=config.store.policies?.[key];if(!policy)return notFound();return `<main class="care-page"><header class="care-heading"><p class="kicker">${esc(policy.kicker)}</p><h1>${esc(policy.title.replace(/\.$/,''))}<em>.</em></h1>${careNavigation(key)}</header><div class="care-layout"><div class="info-content">${policy.sections.map(([heading,body])=>`<section><h2 class="info-heading">${esc(heading)}</h2><p>${fill(body)}</p></section>`).join('')}${config.store.policyUpdated?`<p class="info-updated">Last updated ${esc(config.store.policyUpdated)}</p>`:''}<a href="/shop" data-route class="btn dark-btn">BACK TO THE SHOP ${icon('arrow')}</a></div>${careAside()}</div></main>`;}
function contactPage(){return `<main class="care-page"><header class="care-heading"><p class="kicker">WE’RE HERE TO HELP</p><h1>CONTACT<em>.</em></h1>${careNavigation('contact')}</header><div class="care-layout"><div class="info-content"><section><h2 class="info-heading">Let’s get it sorted.</h2><p>Questions about a product, delivery or a return? Start with the details below.</p><p>${config.supportEmail?`Email ${supportLink()} for product and order questions.`:'Our customer support email will be available before sales open.'}</p></section><section><h2 class="info-heading">About your order</h2><p>Include your order reference and the email address used at checkout so we can find your order.</p></section><section><h2 class="info-heading">Find an answer</h2><p><a href="/info/shipping" data-route>Shipping information ↗</a><br/><a href="/info/returns" data-route>Returns policy ↗</a><br/><a href="/product/fortivor-pre-workout" data-route>Fortivor product information ↗</a></p></section><a href="/shop" data-route class="btn dark-btn">BACK TO THE SHOP ${icon('arrow')}</a></div>${careAside()}</div></main>`;}
function adminToken(){try{return sessionStorage.getItem('auctoran-admin')||'';}catch{return '';}}
function adminPage(){return `<main class="info-page admin-page"><p class="kicker">MANAGE ORDERS</p><h1>ORDERS<em>.</em></h1>${adminToken()?'<div id="admin-orders" class="admin-orders">Loading orders…</div><button class="remove-link" data-action="adminLogout">SIGN OUT</button>':'<form id="admin-login" class="admin-login"><label for="admin-token">ADMIN TOKEN</label><input id="admin-token" type="password" autocomplete="current-password" required/><button class="btn dark-btn" type="submit">VIEW ORDERS</button></form>'}</main>`;}
async function adminFetch(url,options={}){const res=await fetch(url,{...options,headers:{...options.headers,Authorization:'Bearer '+adminToken()}});const data=await res.json();if(res.status===401){try{sessionStorage.removeItem('auctoran-admin')}catch{}render();throw new Error('Invalid admin token');}if(!res.ok)throw new Error(data.error||'Request failed');return data;}
function addressText(a={}){return [a.line1,a.line2,[a.city,a.state,a.postal_code].filter(Boolean).join(' '),a.country].filter(Boolean).map(esc).join('<br/>');}
async function loadAdminOrders(){const target=document.querySelector('#admin-orders');if(!target)return;try{const {orders}=await adminFetch('/api/admin/orders');const open=orders.filter(o=>o.payment==='paid'&&o.fulfillment!=='fulfilled').length;
 target.innerHTML=orders.length?`<p class="admin-summary">${orders.length} orders · <b>${open} to ship</b></p>${orders.map(o=>`<article class="admin-order ${o.fulfillment==='fulfilled'?'done':''}"><div><span class="brand-label">${esc(new Date(o.createdAt).toLocaleString())} · ${o.livemode?'LIVE':'TEST'} · ${esc(o.payment.toUpperCase())}</span><strong>${esc(o.name||o.email)} — ${money(o.totalCents||0)}</strong><p>${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join('<br/>')}</p><small>${esc(o.email)} ${o.phone?'· '+esc(o.phone):''} · ref ${esc(o.id.slice(-8).toUpperCase())}</small></div><div><p>${o.shipping?`<b>${esc(o.shipping.name)}</b><br/>${addressText(o.shipping.address)}`:'No shipping address'}</p></div><div class="admin-actions">${o.fulfillment==='fulfilled'?`<p>Shipped ${o.tracking?'· '+esc(o.tracking):''}</p><button class="remove-link" data-action="adminFulfill" data-id="${esc(o.id)}" data-status="unfulfilled">MARK UNSHIPPED</button>`:`<input placeholder="Tracking number (optional)" data-tracking="${esc(o.id)}"/><button class="btn dark-btn" data-action="adminFulfill" data-id="${esc(o.id)}" data-status="fulfilled" ${o.payment==='paid'?'':'disabled'}>MARK SHIPPED</button>`}</div></article>`).join('')}`:'<p>No orders yet. Paid Stripe orders appear here automatically.</p>';}catch(err){target.textContent=err.message;}}
function orderPage(){const params=new URLSearchParams(location.search);const demo=params.get('demo')==='1';const session=params.get('session_id');if(demo){return `<main class="order-page"><div class="order-icon">${icon('check',38)}</div><p class="kicker">INTERACTIVE DEMONSTRATION</p><h1>THE DEMO<br/><em>IS COMPLETE.</em></h1><p>No payment was collected, no actual order was created, and nothing will ship. Your demo bag is saved. Stripe test checkout can be configured for further testing.</p><a href="/shop" data-route class="btn dark-btn">CONTINUE SHOPPING ${icon('arrow')}</a></main>`;}
 return `<main class="order-page"><div class="order-icon">${icon('shield',36)}</div><p class="kicker">PAYMENT VERIFICATION</p><h1>CHECKOUT<br/><em>STATUS.</em></h1><div id="checkout-status" role="status"><p>${session?'Checking Stripe payment status…':'No checkout session was provided.'}</p></div><a href="/shop" data-route class="btn dark-btn">CONTINUE SHOPPING ${icon('arrow')}</a></main>`;
}
function notFound(){return `<main class="not-found"><p class="kicker">PAGE NOT FOUND</p><h1>OFF THE <em>PATH.</em></h1><p>This page isn't part of the collection.</p><a href="/" data-route class="btn dark-btn">RETURN HOME ${icon('arrow')}</a></main>`;}
function cartDrawer(){return `<div class="drawer-overlay ${view.cartOpen?'active':''}" data-action="closeCart" aria-hidden="${!view.cartOpen}"></div><aside class="cart-drawer ${view.cartOpen?'active':''}" role="dialog" aria-modal="true" aria-label="Shopping bag" aria-hidden="${!view.cartOpen}"><div class="drawer-header"><span>THE BAG <small>(${count()})</small></span><button type="button" class="icon-button" data-action="closeCart" aria-label="Close shopping bag">${icon('close',23)}</button></div>${cart.length?`<div class="drawer-items">${cart.map(cartLine).join('')}</div><div class="drawer-bottom"><div class="drawer-subtotal"><span>SUBTOTAL</span><strong>${money(total())}</strong></div><small>Tax & shipping calculated at checkout.${preview()?' Prices and inventory shown for demonstration until launch.':''}</small><a href="/cart" data-route class="btn dark-btn fullwidth">VIEW BAG & CHECKOUT ${icon('arrow')}</a><button type="button" data-action="closeCart" class="drawer-continue">CONTINUE SHOPPING</button></div>`:`<div class="drawer-empty"><p>YOUR BAG IS EMPTY.</p><button data-action="closeCart" class="btn dark-btn">CONTINUE SHOPPING ${icon('arrow')}</button></div>`}</aside>`;}
function mobileMenu(){return `<div role="dialog" aria-modal="true" aria-label="Navigation menu" class="mobile-nav-panel ${view.menuOpen?'open':''}"><div class="mobile-nav-inner"><button class="menu-close icon-button" data-action="closeMenu" aria-label="Close navigation">${icon('close',24)}</button><p class="kicker">EXPLORE AUCTORAN LABS</p>${[['SHOP ALL','/shop'],['PRE-WORKOUT','/shop?category=pre-workout'],['PROTEIN','/shop?category=protein'],['CREATINE','/shop?category=creatine'],['AMINOS','/shop?category=aminos'],['VITAMINS','/shop?category=vitamins'],['FAT BURNERS','/shop?category=fat-burners'],['BUILD YOUR STACK','/build-your-stack'],['ABOUT US','/about']].filter(([,url])=>!url.includes('category=')||hasCategory(url.split('=')[1])).map(([name,url],i)=>`<a href="${url}" data-route>${name}${icon('northeast',22)}</a>`).join('')}</div></div>`;}
function searchPanel(){return `<div class="search-cover ${view.searchOpen?'open':''}" role="dialog" aria-modal="true" aria-hidden="${!view.searchOpen}" aria-label="Search products"><div class="search-panel"><button type="button" data-action="closeSearch" class="search-exit" aria-label="Close search">${icon('close',25)}</button><p class="kicker">FIND YOUR FORM</p><form id="site-search-form"><label for="site-search">WHAT ARE YOU LOOKING FOR?</label><div class="search-form-row"><input id="site-search" type="search" name="q" autocomplete="off" placeholder="Pre-workout, protein, creatine…" value="${esc(view.query)}"/><button type="submit" aria-label="Submit search">${icon('arrow',27)}</button></div></form><p class="search-hint">POPULAR: ${navLink('pre-workout','PRE-WORKOUT')}${navLink('creatine','CREATINE')}${navLink('protein','PROTEIN')}</p></div></div>`;}
let previousModal = null, restoreFocus = null, purchaseObserver = null;
function activeModal(){return view.cartOpen?document.querySelector('.cart-drawer'):view.searchOpen?document.querySelector('.search-cover'):view.menuOpen?document.querySelector('.mobile-nav-panel'):null;}
function syncModal(){
 const modal=activeModal();
 for(const selector of ['.cart-drawer','.search-cover','.mobile-nav-panel']){const el=document.querySelector(selector);if(el){el.inert=el!==modal;el.setAttribute('aria-hidden',String(el!==modal));}}
 document.querySelectorAll('main,.site-header,.footer,.notice-strip,.preview-strip,.skip-link').forEach(el=>el.inert=Boolean(modal));
 document.body.classList.toggle('modal-open',Boolean(modal));
 const key=modal?.className.split(' ')[0]||null;
 if(key!==previousModal){if(modal){restoreFocus=document.activeElement;modal.querySelector('button,input,a')?.focus({preventScroll:true});}else{if(restoreFocus?.isConnected)restoreFocus.focus({preventScroll:true});else document.querySelector('.cart-toggle')?.focus({preventScroll:true});restoreFocus=null;}previousModal=key;}
 const menuButton=document.querySelector('[data-action="openMenu"]');menuButton?.setAttribute('aria-expanded',String(view.menuOpen));
}
function refreshShell(){
 const badge=document.querySelector('.cart-counter');if(badge)badge.textContent=count();document.querySelector('.cart-toggle')?.setAttribute('aria-label',`Open shopping bag, ${count()} items`);
 const focused=document.activeElement;const action=focused?.dataset?.action,id=focused?.dataset?.id;
 const existing=document.querySelector('.cart-drawer');if(existing){const frag=document.createElement('div');frag.innerHTML=cartDrawer();existing.replaceWith(frag.querySelector('.cart-drawer'));}
 document.querySelector('.drawer-overlay')?.classList.toggle('active',view.cartOpen);
 document.querySelector('.mobile-nav-panel')?.classList.toggle('open',view.menuOpen);
 document.querySelector('.search-cover')?.classList.toggle('open',view.searchOpen);
 syncModal();
 if(view.cartOpen&&action&&previousModal==='cart-drawer')document.querySelector(`.cart-drawer [data-action="${CSS.escape(action)}"]${id?'[data-id="'+CSS.escape(id)+'"]':''}`)?.focus({preventScroll:true});
 const toaster=document.querySelector('.toast');if(toaster){toaster.textContent=view.toast;toaster.classList.toggle('shown',Boolean(view.toast));}
}
function observePurchase(){
 purchaseObserver?.disconnect();const controls=document.querySelector('#primary-purchase'),bar=document.querySelector('.mobile-purchase');
 if(controls&&bar){purchaseObserver=new IntersectionObserver(entries=>{bar.hidden=entries[0].isIntersecting;},{rootMargin:'-76px 0px 0px 0px',threshold:0});purchaseObserver.observe(controls);}
}
function updateQuantity(){
 const p=products.find(p=>p.slug===location.pathname.split('/').pop());if(!p)return;
 document.querySelector('.purchase-controls output').textContent=view.detailQty;
 document.querySelector('.add-detail').innerHTML=`${p.demoAvailable?'ADD TO DEMO BAG':'ADD TO BAG'} — ${money(p.priceCents*view.detailQty)} ${icon('arrow',20)}`;
 const price=document.querySelector('.mobile-purchase span');if(price)price.textContent=money(p.priceCents*view.detailQty)+(p.demoAvailable?' · PREVIEW':'');
}
function showPhoto(id,index){
 const p=byId(id);if(!p)return;const photos=productGallery(p);view.galleryIndex=(index+photos.length)%photos.length;
 const media=document.querySelector('.detail-media');if(media)media.innerHTML=detailGallery(p);
}
function setZoom(dialog,enlarged){
 if(!dialog)return;
 dialog.dataset.zoomed=String(enlarged);
 const button=dialog.querySelector('.zoom-scale');
 button.textContent=enlarged?'FULL VIEW':'ZOOM IN';
 button.setAttribute('aria-pressed',String(enlarged));
 dialog.querySelector('.zoom-help').textContent=enlarged?'Scroll or swipe to inspect. Select Full view to see the whole image.':'Whole image. Select Zoom in for label detail. Escape to close.';
 const content=dialog.querySelector('.zoom-content'),image=content.querySelector('img');
 image?.decode().then(()=>{
  if(!dialog.open)return;
  content.scrollTo({left:Math.max(0,(content.scrollWidth-content.clientWidth)/2),top:Math.max(0,(content.scrollHeight-content.clientHeight)/2)});
 }).catch(()=>{});
}
function showZoom(id){
 const p=byId(id),dialog=document.querySelector('#gallery-zoom');if(!p||!dialog)return;
 const photo=productGallery(p)[view.galleryIndex||0];
 dialog.querySelector('.zoom-toolbar p').textContent=`${p.name} / ${photo.label}`;
 dialog.querySelector('.zoom-content').innerHTML=galleryPhoto({...photo,sizes:'(max-width:700px) 200vw, 100vw'},{hero:true});
 dialog.showModal();
 setZoom(dialog,true);
}
function render(){try{renderContent();}catch(error){console.error('Store render failed',error);app.innerHTML='<main class="fatal"><h1>LET’S TRY THAT AGAIN.</h1><p>This page could not be displayed. Your bag is saved.</p><a href="/">RETURN HOME</a><button data-action="reload">RELOAD THE STORE</button></main>';}}
function renderContent(){
 const pathname=decodeURIComponent(location.pathname);
 let page=pathname==='/'?home():pathname==='/shop'?shop():pathname.startsWith('/product/')?detail(pathname.split('/').pop()):pathname==='/build-your-stack'?stackPage():pathname==='/cart'?cartPage():pathname==='/about'?about():pathname.startsWith('/info/')?policyPage(pathname.slice(6)):pathname==='/contact'?contactPage():pathname==='/admin'?adminPage():pathname==='/order/success'?orderPage():notFound();
 app.innerHTML='<a href="#main-content" class="skip-link">Skip to content</a>'+header()+page+footer()+cartDrawer()+mobileMenu()+searchPanel()+`<div class="toast ${view.toast?'shown':''}" role="status">${esc(view.toast)}</div>`;
 document.body.classList.toggle('modal-open',view.cartOpen||view.searchOpen||view.menuOpen);
 document.title=pathname==='/'?'Auctoran Labs — Performance Supplements':`${pathname.startsWith('/product/')?byId(pathname.split('/').pop())?.fullName||'Product':pathname==='/shop'?'Supplements':pathname==='/cart'?'Your Bag':pathname.startsWith('/info/')?(config.store.policies?.[pathname.slice(6)]?.title.replace(/\.$/,'')||'Not found'):pathname==='/contact'?'Contact':pathname==='/admin'?'Orders':pathname==='/order/success'?'Order Status':'About Us'} — Auctoran Labs`;
 const main=document.querySelector('main');if(main){main.id='main-content';main.tabIndex=-1;}
 syncModal();observePurchase();
 const currentProduct=pathname.startsWith('/product/')?products.find(p=>p.slug===pathname.split('/').pop()):null;
 const description=currentProduct?`Explore ${currentProduct.fullName} by ${currentProduct.brand}${currentProduct.flavor?`: ${currentProduct.flavor}`:''}. Read formula information, caffeine warnings and product availability.`:pathname==='/build-your-stack'?'Build a considered supplement selection with transparent catalog matching, stimulant preferences and your budget.':'Auctoran Labs performance supplements. Discover Fortivor and considered training essentials.';
 document.querySelector('meta[name="description"]')?.setAttribute('content',description);
 if(pathname==='/build-your-stack')document.title='Build Your Stack — Auctoran Labs';
 document.querySelector('#product-schema')?.remove();
 if(pathname.startsWith('/product/')){const p=products.find(p=>p.slug===pathname.split('/').pop());if(p&&!p.isSample&&p.labelVerified&&p.priceConfirmed&&p.inventoryConfirmed){const schema=document.createElement('script');schema.id='product-schema';schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Product',name:p.fullName,brand:{'@type':'Brand',name:p.brand},image:location.origin+p.image,offers:{'@type':'Offer',url:location.href,priceCurrency:'USD',price:(p.priceCents/100).toFixed(2),availability:'https://schema.org/'+(p.inStock?'InStock':'OutOfStock')}});document.head.append(schema);}}
 if(pathname==='/admin')loadAdminOrders();
 if(pathname==='/order/success'&&new URLSearchParams(location.search).has('session_id'))verifyCheckout();
}
async function verifyCheckout(){const session=new URLSearchParams(location.search).get('session_id');try{const res=await fetch('/api/checkout/verify?session_id='+encodeURIComponent(session));const result=await res.json();const target=document.querySelector('#checkout-status');if(!target)return;if(!res.ok)throw new Error(result.error||'Cannot verify checkout');if(result.paymentStatus==='paid'){cart=[];saveCart();refreshShell();target.innerHTML=`<p><strong>${result.livemode?'Payment confirmed — thank you.':'STRIPE TEST COMPLETE — no real payment.'}</strong> ${result.livemode?'We received your payment of':'Test amount:'} ${money(result.total)}${result.email?` and sent a receipt to ${esc(result.email)}`:''}. Your order reference is <b>${esc(result.reference)}</b>. ${result.livemode?'We will email you when it ships.':'No real order will ship.'}</p>`;}else target.innerHTML=`<p>Payment status: ${esc(result.paymentStatus)}. Check the receipt or Stripe dashboard before assuming an order is complete.</p>`;}catch(err){const target=document.querySelector('#checkout-status');if(target)target.textContent=err.message;}}
async function checkout(){if(view.checkoutLoading||!cart.length)return;view.checkoutLoading=true;const button=document.querySelector('[data-action="checkout"]');if(button){button.disabled=true;button.textContent='PREPARING CHECKOUT…';}try{const res=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart.map(({id,qty})=>({id,qty}))})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Checkout could not be started');if(!data.url)throw new Error('No checkout destination available');if(data.url.startsWith('/') && !data.url.startsWith('//'))navigate(data.url);else if(/^https:\/\/checkout\.stripe\.com\//.test(data.url))window.location.assign(data.url);else throw new Error('Unexpected checkout destination');}catch(err){const error=document.querySelector('#checkout-error');if(error)error.textContent=err.message;notify(err.message);view.checkoutLoading=false;if(button){button.disabled=false;button.innerHTML=`${config.mode==='demo'?'TRY DEMO CHECKOUT':'SECURE CHECKOUT'} ${icon('arrow')}`;}}}

function renderStack(focus=true){const scroll=window.scrollY;const focused=document.activeElement;const action=focused?.dataset?.action,id=focused?.dataset?.id;render();if(!focus&&action)document.querySelector(`[data-action="${CSS.escape(action)}"]${id?'[data-id="'+CSS.escape(id)+'"]':''}`)?.focus({preventScroll:true});if(focus){document.querySelector('.stack-stage')?.setAttribute('tabindex','-1');document.querySelector('.stack-stage')?.focus({preventScroll:true});}window.scrollTo(0,scroll);}
function stackQuantity(id,delta){stack.selection[id]=Math.max(1,Math.min(20,(stack.selection[id]||1)+delta));renderStack(false);}
function addSelection(ids){
 if(stack.budgetCents&&stackTotal()>Number(stack.budgetCents)){notify('Selected quantities exceed your budget. Adjust them before adding.');return;}
 const entries=ids.map(id=>({id,qty:stack.selection[id]||1})).filter(i=>canBuy(byId(i.id)));
 cart=normalizeCart([...cart,...entries],products);saveCart();view.cartOpen=true;refreshShell();
}
document.addEventListener('click',async e=>{
 const link=e.target.closest('a[data-route]');if(link){if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;e.preventDefault();navigate(link.getAttribute('href'));return;}
 const button=e.target.closest('[data-action]');if(!button||button.disabled)return;
 const {action,id}=button.dataset;
 if(action==='openCart'){view.cartOpen=true;view.searchOpen=false;view.menuOpen=false;refreshShell();}
 else if(action==='closeCart'){view.cartOpen=false;refreshShell();}
 else if(action==='openMenu'){view.menuOpen=!view.menuOpen;view.cartOpen=false;view.searchOpen=false;refreshShell();}
 else if(action==='closeMenu'){view.menuOpen=false;refreshShell();}
 else if(action==='openSearch'){view.searchOpen=true;view.cartOpen=false;view.menuOpen=false;refreshShell();document.querySelector('#site-search')?.focus();}
 else if(action==='closeSearch'){view.searchOpen=false;refreshShell();}
 else if(action==='add')addCart(id);
 else if(action==='addDetail')addCart(id,view.detailQty);
 else if(action==='remove')removeCart(id);
 else if(action==='increase')changeCart(id,1);
 else if(action==='decrease')changeCart(id,-1);
 else if(action==='detailPlus'){const p=byId(document.querySelector('.add-detail')?.dataset.id);view.detailQty=Math.min(p?.inventoryConfirmed?Math.min(20,p.inventoryQuantity):20,view.detailQty+1);updateQuantity();}
 else if(action==='detailMinus'){view.detailQty=Math.max(1,view.detailQty-1);updateQuantity();}
 else if(action==='showDetailImage')showPhoto(id,Number(button.dataset.photo));
 else if(action==='galleryNext')showPhoto(id,view.galleryIndex+1);
 else if(action==='galleryPrevious')showPhoto(id,view.galleryIndex-1);
 else if(action==='zoomGallery')showZoom(id);
 else if(action==='toggleZoom')setZoom(document.querySelector('#gallery-zoom'),document.querySelector('#gallery-zoom')?.dataset.zoomed!=='true');
 else if(action==='closeZoom')document.querySelector('#gallery-zoom')?.close();
 else if(action==='stackGoal'){stack.goal=id;const next=document.querySelector('[data-action="stackNext"]');if(next)next.disabled=false;document.querySelectorAll('.goal-choice').forEach(el=>{const selected=el.dataset.id===id;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));el.querySelector('.goal-check').innerHTML=icon(selected?'check':'northeast',17);});}
 else if(action==='stackNext'){if(stack.step===1&&!stack.goal)return;stack.step=Math.min(3,stack.step+1);if(stack.step===3){stack.removed=[];stack.selection=Object.fromEntries(stackResults().map(r=>[r.product.id,1]));}renderStack();document.querySelector('.stack-workspace')?.scrollIntoView({behavior:'smooth',block:'start'});}
 else if(action==='stackBack'){stack.step=Math.max(1,stack.step-1);renderStack();}
 else if(action==='stackReset'){stack={step:1,goal:'',categories:[],stimulant:'any',budgetCents:'',allowPreview:false,selection:{},removed:[]};renderStack();}
 else if(action==='stackMinus')stackQuantity(id,-1);
 else if(action==='stackPlus')stackQuantity(id,1);
 else if(action==='stackRemove'){stack.selection[id]=0;stack.removed=[...(stack.removed||[]),id];renderStack();}
 else if(action==='addStackSingle')addSelection([id]);
 else if(action==='addStack')addSelection(selectedStack().map(r=>r.product.id));
 else if(action==='checkout')await checkout();
 else if(action==='reload')location.reload();
 else if(action==='adminLogout'){try{sessionStorage.removeItem('auctoran-admin')}catch{}render();}
 else if(action==='adminFulfill'){button.disabled=true;const tracking=document.querySelector(`[data-tracking="${CSS.escape(id)}"]`)?.value||'';try{await adminFetch('/api/admin/orders/'+encodeURIComponent(id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fulfillment:button.dataset.status,tracking})});await loadAdminOrders();}catch(err){notify(err.message);button.disabled=false;}}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='admin-login'){e.preventDefault();try{sessionStorage.setItem('auctoran-admin',e.target.querySelector('#admin-token').value)}catch{}render();return;}
 if(e.target.id==='site-search-form'){e.preventDefault();const q=new FormData(e.target).get('q')?.trim()||'';navigate('/shop'+(q?'?q='+encodeURIComponent(q):''));}
 if(e.target.id==='catalog-search'){e.preventDefault();navigate(filterUrl('q',new FormData(e.target).get('q')?.trim()||''));}
});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-filter]')){const key=e.target.dataset.filter;history.replaceState({},'',filterUrl(key,e.target.value));render();document.querySelector(`[data-filter="${key}"]`)?.focus({preventScroll:true});}
 if(e.target.name==='stack-category')stack.categories=[...document.querySelectorAll('[name="stack-category"]:checked')].map(el=>el.value);
 if(e.target.name==='stack-stimulant')stack.stimulant=e.target.value;
 if(e.target.id==='stack-budget')stack.budgetCents=e.target.value;
 if(e.target.id==='stack-preview')stack.allowPreview=e.target.checked;
 if(e.target.matches('[data-stack-select]')){stack.selection[e.target.dataset.stackSelect]=e.target.checked?1:0;renderStack(false);}
});
document.addEventListener('keydown',e=>{
 const modal=activeModal();
 if(e.key==='Escape'&&!document.querySelector('dialog[open]')){view.cartOpen=false;view.menuOpen=false;view.searchOpen=false;refreshShell();}
 if(e.key==='Tab'&&modal){const focusable=[...modal.querySelectorAll('a,button,input,select,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();view.searchOpen=true;view.cartOpen=false;view.menuOpen=false;refreshShell();document.querySelector('#site-search')?.focus();}
});
let touchStart=null;
document.addEventListener('touchstart',e=>{if(e.target.closest('.detail-gallery-image'))touchStart={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY};},{passive:true});
document.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5){const id=document.querySelector('.detail-gallery-image')?.dataset.id;if(id)showPhoto(id,view.galleryIndex+(dx<0?1:-1));}},{passive:true});
window.addEventListener('popstate',()=>{view.cartOpen=false;view.menuOpen=false;view.searchOpen=false;view.galleryIndex=0;render();});
window.addEventListener('storage',e=>{if(e.key==='auctoran-cart-v1'){cart=normalizeCart(loadCart(),products);if(location.pathname==='/cart')render();else refreshShell();}});
window.addEventListener('resize',()=>{if(window.innerWidth>900&&view.menuOpen){view.menuOpen=false;refreshShell();}});
async function start(){try{const [productsResponse,configResponse]=await Promise.all([fetch('/api/products'),fetch('/api/config')]);if(!productsResponse.ok||!configResponse.ok)throw new Error('Store API unavailable');products=(await productsResponse.json()).products;config=await configResponse.json();cart=normalizeCart(cart,products);saveCart();render();}catch(err){app.innerHTML=`<div class="fatal"><h1>THE STORE IS TEMPORARILY UNAVAILABLE.</h1><p>${esc(err.message)}</p><button data-action="reload">TRY AGAIN</button></div>`;}}
start();
